### Preparation


::: {.cell filename='Load prepared data'}

```{.r .cell-code .hidden}
#| filename: Load prepared data
colors <- ggsci::pal_jco()(3) |> set_names(c("glasses", "chest", "wrist"))
load(here("data/prepared_time_data.RData"))
time_data <- 
  time_data |> 
  mutate(position = fct(position, levels = c("glasses", "chest", "wrist")))
```
:::



::: {.cell filename='Overview plot of the data (median with IQR)'}

```{.r .cell-code .hidden}
#| filename: Overview plot of the data (median with IQR)
time_data|>
  group_by(position) |> 
  mutate(position = fct_relevel(position, "glasses")) |> 
  aggregate_Date(
    date.handler = \(x) ymd("2025-01-01"),
    numeric.handler = \(x) median(x, na.rm = TRUE),
    p75 = quantile(MEDI, p=0.75, na.rm = TRUE),
    p25 = quantile(MEDI, p=0.25, na.rm = TRUE)
  ) |> 
  gg_doubleplot(geom = "blank", jco_color = FALSE, facetting = FALSE,
                x.axis.breaks.repeat = ~Datetime_breaks(.x, by = "12 hours", shift =
    lubridate::duration(0, "hours"))) +
  geom_ribbon(aes(ymin = p25, ymax = p75, fill = position), alpha = 0.5) +
  geom_line(aes(color = position)) +
  geom_hline(yintercept = 250, linetype = "dashed") +
  scale_color_jco()+
  scale_fill_jco() +
  guides(fill = "none") +
  theme(panel.spacing = unit(2, "lines"))
```

::: {.cell-output-display}
![](JZ_HGAM_analysis_files/figure-html/unnamed-chunk-3-1.png){width=672}
:::
:::



::: {.cell filename='H11 formulas'}

```{.r .cell-code .hidden}
#| filename: H11 formulas
formula_1 <- lzMEDI ~ s(Time, k = 12) + s(Time, position, bs = "sz", k = 12) + s(Time, site, bs = "sz", k = 12) + s(Time, Id, bs = "fs") + s(Id_date, bs = "re")
formula_0 <- lzMEDI ~ s(Time, k = 12) + s(Time, site, bs = "sz", k = 12) + s(Time, Id, bs = "fs") + s(Id_date, bs = "re")
```
:::


### Analysis

#### Base model


::: {.cell filename='Main model'}

```{.r .cell-code .hidden}
#| filename: Main model
model_1 <- 
  bam(formula_1, 
      data = time_data, 
      discrete = TRUE,
      method = "fREML",
      nthreads = 10
      )

r1 <- start_value_rho(model_1, 
                      plot=TRUE)
```

::: {.cell-output-display}
![](JZ_HGAM_analysis_files/figure-html/unnamed-chunk-5-1.png){width=672}
